/* Bank soal ENGLISH tambahan: structure, written expression, dan vocabulary in context (tingkat 2–4).
 * Structure: [kalimat ____, JAWABAN BENAR, pengecoh x3, pembahasan] (4 opsi gaya TOEFL ITP).
 * Written expression (type 'we'): kalimat dengan bagian [A|…] [B|…] [C|…] [D|…], lalu huruf bagian yang salah.
 * Vocabulary: V('kalimat dengan [[kata]]', BENAR, pengecoh x3, 'arti') → stem "closest in meaning to".
 */
const V = (s, ans, d1, d2, d3, idn) => {
  const m = s.match(/\[\[(.+?)\]\]/);
  return [`${s.replace(m[0], `<b>${m[1]}</b>`)}<br>The word "${m[1]}" is closest in meaning to …`, ans, d1, d2, d3, `${m[1]} = ${idn}.`];
};

